public class ForwardingProxy<T> : DispatchProxy
{
    private T? _inner;
    public static T Create(T inner)
    {
        var proxy = Create<T, ForwardingProxy<T>>();
        ((ForwardingProxy<T>)(object)proxy)._inner = inner;
        return proxy;
    }
    protected override object? Invoke(MethodInfo target, object?[]? args)
        => target.Invoke(_inner, args);                 // every interface call lands here
}
